<style scoped lang="scss" src="./label.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import {
  LabelMode,
  LabelModeValues,
  LabelAlign,
  LabelAlignValues,
} from "./label.constants";
import { has } from "../../util/has";

/**
 * This is a Label component to wrap around some common label styles that are
 * available throughout the application.
 *
 * Simply wrap a blurb of text with this component.
 */
@Component
export default class Label extends Vue {
  @Prop({
    type: String,
    default: LabelMode.LARGE_TITLE,
    validator: has(LabelModeValues),
  })
  mode;

  @Prop({
    type: String,
    default: LabelAlign.LEFT,
    validator: has(LabelAlignValues),
  })
  align;

  @Prop({ type: Boolean, default: false }) multiline;

  get modeClass() {
    return this.mode;
  }

  get alignClass() {
    return this.align;
  }

  get multilineClass() {
    return this.multiline ? "Label--multiline" : "";
  }
}
</script>

<template>
  <div :class="['Label', modeClass, alignClass, multilineClass]">
    <slot />
  </div>
</template>
